<?php
$dir = 'includes/Watchlist/';
$files = glob($dir . '*.php');

foreach ($files as $file) {
    echo "\n=== $file ===\n";
    $content = file_get_contents($file);

    // Find all public methods (not constructors, not in interfaces)
    preg_match_all('/public\s+(static\s+)?function\s+(\w+)\s*\(/', $content, $matches);

    foreach ($matches[2] as $method) {
        if ($method === '__construct' || $method === '__destruct') {
            continue;
        }

        // Skip if this is an interface or trait
        if (strpos($content, 'interface ') !== false || strpos($content, 'trait ') !== false) {
            if (strpos($content, "function $method") === strpos($content, "public function $method") - strlen("public ")) {
                continue;
            }
        }

        echo "  - $method\n";
    }
}
EOF
